// One-off: the owner's three perk choices (Nov 13): pistol Steady Grip -> Quick Draw, shotgun Steady Grip -> +2 shells,
// rifle gets Extended Mag. Edits Skills.json in place, keeping its text layout.
const fs = require('fs');
const file = process.argv[2];
let t = fs.readFileSync(file, 'utf8');
const nl = t.includes('\r\n') ? '\r\n' : '\n';

function nodeBlock(n) {
	const lines = [
		`\t\t\t"Id": "${n.id}",`,
		`\t\t\t"Tree": "Weapon",`,
		`\t\t\t"Branch": "${n.branch}",`,
		`\t\t\t"DisplayName": "${n.name}",`,
		`\t\t\t"Description": "${n.desc}",`,
		`\t\t\t"Cost": ${n.cost || 1},`,
		`\t\t\t"MaxRank": 3,`,
		`\t\t\t"Requires": [ "${n.req}" ],`,
		`\t\t\t"ModifiersPerRank": [ ${n.mods.map((m) => `{ "Stat": "${m[0]}", "Op": "${m[1]}", "Value": ${m[2]} }`).join(', ')} ],`,
		`\t\t\t"Column": ${n.col},`,
		`\t\t\t"Row": ${n.row}`,
	];
	return '\t\t{' + nl + lines.join(nl) + nl + '\t\t}';
}
function replaceNode(id, n) {
	const at = t.indexOf(`"Id": "${id}"`);
	if (at < 0) throw new Error('missing ' + id);
	const start = t.lastIndexOf('\t\t{', at);
	const end = t.indexOf(nl + '\t\t}', at) + (nl + '\t\t}').length;
	t = t.slice(0, start) + nodeBlock(n) + t.slice(end);
}
function insertAfter(id, n) {
	const at = t.indexOf(`"Id": "${id}"`);
	if (at < 0) throw new Error('missing ' + id);
	const end = t.indexOf(nl + '\t\t}', at) + (nl + '\t\t}').length;
	t = t.slice(0, end) + ',' + nl + nodeBlock(n) + t.slice(end);
}

replaceNode('Weapon_Pistol_Recoil', { id: 'Weapon_Pistol_QuickDraw', branch: 'Pistol', name: 'Quick Draw',
	desc: 'Pistol: aim 20% faster and move 10% faster while aiming, per rank.', req: 'Weapon_Pistol_FireRate',
	mods: [['Weapon.Pistol.AimTime', 'Multiply', 0.8], ['Weapon.Pistol.AimMoveSpeedMult', 'Add', 0.1]], col: 2, row: 1 });
replaceNode('Weapon_Shotgun_Recoil', { id: 'Weapon_Shotgun_Shells', branch: 'Shotgun', name: 'Extended Tube',
	desc: 'Shotgun: the tube holds 2 more shells per rank.', req: 'Weapon_Shotgun_FireRate',
	mods: [['Weapon.Shotgun.MagazineSize', 'Add', 2]], col: 2, row: 1 });
insertAfter('Weapon_RifleFar', { id: 'Weapon_Rifle_ExtendedMag', branch: 'Rifle', name: 'Extended Mag',
	desc: 'Rifle: 5 more rounds per magazine per rank.', req: 'Weapon_RifleFar',
	mods: [['Weapon.Rifle.MagazineSize', 'Add', 5]], col: 0, row: 1 });

fs.writeFileSync(file, t);
const parsed = JSON.parse(t);
const ids = new Set(parsed.Skills.map((s) => s.Id));
for (const s of parsed.Skills) for (const r of s.Requires || []) if (!ids.has(r)) throw new Error(s.Id + ' requires missing ' + r);
console.log('ok', parsed.Skills.length, 'nodes');

