// One-off: GDD v0.43, the enchant's element is chosen in its QTE, on fixed keys.
const fs = require('fs');
const f = process.argv[2];
let t = fs.readFileSync(f, 'utf8');
const r = (a, b) => { const n = t.split(a).length - 1; if (n !== 1) throw new Error(n + ' x ' + a.slice(0, 60)); t = t.split(a).join(b); };
r('Status: **v0.42, 2026-11-13**', 'Status: **v0.43, 2026-11-13**');
r('- v0.42 (2026-11-13): owner chose three perk changes',
	'- v0.43 (2026-11-13): owner: **the weapon enchant\'s element is chosen in its QTE**, always in the same places (never shuffled): a first step shows fire (A / Square), lightning (W / Triangle) and ice (D / Circle); the key picks it, then the usual key sequence and gesture follow. Also from the owner the same day: menus play a transition when their look changes, every skill point asks for confirmation, and the weapon tree is a hub with gun pages (v0.39 to v0.42).\n- v0.42 (2026-11-13): owner chose three perk changes');
r('- **Element:** chosen by the player when equipping the spell.',
	'- **Element:** chosen by the player **in the enchant\'s QTE** (owner, v0.43). Its first step shows the three elements, always in the same places: **A / Square = fire, W / Triangle = lightning, D / Circle = ice** (W sits a little higher, as on the keyboard), with the current element marked. The key picks it and the usual part 1 and part 2 follow. The step has its own time (`QTE.ChoiceTimeLimit` in `QTE.json`, 3 s, provisional) so it never eats the QTE\'s own time; if it runs out the element stays as it was. With the QTE switched off, the element is the one set in the inventory\'s Spells page (that picker stays).');
fs.writeFileSync(f, t);
console.log('ok');

